mapper.select:
SELECT

FROM health_metric_record
WHERE id = #{id}
  AND patient_id = #{patientId}
  AND is_deleted = 0
LIMIT 1

SELECT

FROM health_metric_record
WHERE patient_id = #{patientId}
  AND metric_type = #{metricType}
  AND is_deleted = 0
  AND measured_at >= #{fromTime}
ORDER BY measured_at ASC, id ASC

SELECT

FROM health_metric_record
WHERE patient_id = #{patientId}
  AND is_deleted = 0

    AND metric_type = #{metricType}

ORDER BY measured_at DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE health_metric_record
SET is_deleted = 1
WHERE id = #{id}
  AND patient_id = #{patientId}
  AND is_deleted = 0
